#!/usr/bin/env python3
from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT)) if str(ROOT) not in sys.path else None
from data.story_quest_content import STORY_QUEST_REGISTRY,STORY_QUEST_TEXT
updates={51: {'acceptance_text': 'Перемога над Ватажком повернула спокій на дорогу через Початок Шляху, але ненадовго. Наші мисливці простежили рунічний слід до старого прикордонного шляху, що веде в Темний Бір.\n\nКілька тижнів тому там почали з’являтися гоблінські дозори. Спочатку вони ховалися серед дерев, але тепер перекривають стежки й не пропускають людей углиб лісу. Учора з розвідки не повернулися двоє мисливців.\n\nМіська варта не може вирушити туди без підготовки. Поки що ми знаємо лише те, що загроза з Початку Шляху не зникла, а простяглася до кордону Темного Бору.', 'completion_text': 'Староста завершує доповідь про зниклих мисливців, гоблінські дозори та рунічний слід, що веде до Темного Бору.'}, 55: {'acceptance_text': 'Цей знак не схожий на випадковий трофей. Гобліни встановили його на нашому старому прикордонному шляху, де раніше проходили мисливці й торгові вози. Вони оголосили цю землю своєю без жодного нападу на місто й без відкритої вимоги.\n\nЯкщо за дозорами стоїть єдиний ватажок, він намагається відрізати Темний Бір від решти земель і приховати те, що відбувається в глибині.\n\nЯ залишу знак у Ратуші як доказ того, що гобліни свідомо встановлюють нову межу біля міських земель.', 'completion_text': 'Староста приймає гоблінський знак і підтверджує, що дозори свідомо встановлюють новий кордон на старому прикордонному шляху.'}, 56: {'acceptance_text': 'Після твоєї знахідки ми повторно перевірили старий шлях. За першою лінією дозорів стоїть тимчасовий табір. Гобліни використовують його як перевалочний пункт: звідти виходять патрулі, туди приносять припаси й там змінюють варту.\n\nПоки табір діє, наші розвідники не зможуть пройти далі. Зачисти шлях і змусь його варту відступити вглиб Темного Бору.', 'completion_text': 'Прикордонний табір утратив охорону. Гоблінські загони відступили, а старий шлях став доступним для подальшої розвідки.'}, 58: {'acceptance_text': 'Цей метал не належить старим міським рунам. Він грубо оброблений, але символ нанесено точно. Подивись на зламані лінії: у них повторюється той самий вузол, який ми бачили на слідах корупції біля лігва Ватажка.\n\nАмулет не створював силу сам по собі. Він проводив її від іншого джерела й передавав носієві. Ватажок міг отримати подібний предмет від тих самих істот, що зараз керують гоблінськими дозорами.\n\nЯ залишу уламок для подальшого дослідження. Його руна підтверджує зв’язок між подіями на Початку Шляху та загрозою у Темному Борі.'}, 60: {'acceptance_text': 'Отже, гобліни встановили власну межу, укріпили старий шлях і отримують рунічні амулети з глибини Темного Бору. Ватажок був не джерелом корупції, а лише одним із тих, кого вона підсилила.\n\nЦе пояснює, чому після його загибелі рунічний слід не зник. Хтось продовжує виготовляти або роздавати ці предмети, а гоблінські дозори захищають дорогу до джерела.\n\nТвоєї доповіді достатньо, щоб підтвердити: загроза Темного Бору організована й пов’язана з подіями на Початку Шляху. Перша розвідка завершена.'}}
for number,fields in updates.items():
 q=next(q for q in STORY_QUEST_REGISTRY.values() if q.number==number)
 text=STORY_QUEST_TEXT[q.quest_id]
 for field,value in fields.items():assert text[field]==value
for number,phrases in {51: ('Поговори з Головою Найманців', 'організує першу розвідку'), 55: ('Повернися до Голови Найманців', 'повноцінна зачистка', 'потрібно очистити старий шлях'), 56: ('Особливо уважно оглядай', 'символи або уламки', 'обгорілі дерев’яні підвіски', 'синюватого світіння'), 58: ('Голова Найманців має знати',), 60: ('Я затверджую подальшу операцію', 'серію вилазок', 'хто командує дозорами', 'звідки вони отримують накази')}.items():
 q=next(q for q in STORY_QUEST_REGISTRY.values() if q.number==number)
 text=STORY_QUEST_TEXT[q.quest_id]
 merged=text['acceptance_text']+'\n'+text['completion_text']
 for phrase in phrases:assert phrase not in merged
candidate=json.loads((ROOT/'Квести/ROM_квести_Темний_Бір_candidate.json').read_text(encoding='utf-8-sig'))
for number,fields in updates.items():
 q=next(q for q in candidate['quests'] if q['number']==number)
 for field,value in fields.items():assert q[field]==value
assert tuple(q.number for q in STORY_QUEST_REGISTRY.values())==tuple(range(1,61))
print('PASS: Stage 19.29.5')
